#include "audio_ds.h"
#include <nds.h>
#include <maxmod9.h>
#include <stdio.h>

/* Optional bank contract: the first three samples are move, confirm, cancel.
 * The bank is generated by Maxmod's mmutil from licensed private samples.
 * Do not embed any proprietary audio in the public repository. */
static int ready;
static unsigned char loaded[MDS_AUDIO_EVENT_COUNT];

int mds_audio_init(void)
{
 if(ready)return 1;
 FILE *f=fopen("nitro:/soundbank.bin","rb");
 if(!f)return 0; /* Headless/asset-free ROM stays quiet. */
 fclose(f);
 soundEnable();
 if(!mmInitDefault("nitro:/soundbank.bin"))return 0;
 for(unsigned i=0;i<MDS_AUDIO_EVENT_COUNT;i++)
  loaded[i]=mmLoadEffect(i)==0;
 ready=1;
 return 1;
}
int mds_audio_ready(void){return ready;}
void mds_audio_play(MdsAudioEvent event)
{
 if(!ready||(unsigned)event>=MDS_AUDIO_EVENT_COUNT||
    !loaded[(unsigned)event])return;
 mmEffect((unsigned)event);
}
